-- Carga de alumnos.csv. Supabase → SQL Editor → Run.
begin;
alter table public.tesis_docentes alter column folio drop not null;
alter table public.tesis_docentes add column if not exists punto text;
delete from public.tesis;
delete from public.alumnos;
delete from public.docentes;
select setval('public.folio_seq', greatest(1874, coalesce((select max(folio) from public.tesis_docentes), 1874)), true);
commit;
